    unsigned int max_buf_size;     /**< max buff size could allocate, */
    unsigned int page_type;        /**< page type of memzone, could be PAGE_NORMAL or PAGE_HUGET_ONLY */
    int reserve[BUFF_RESERVE_LEN]; /**< for reserve */
};

